content.content:
1	import Anthropic from "@anthropic-ai/sdk";
2	import { z } from "zod";
3	import { forStructuredOutput } from "@/lib/ai/tagging-schema";
4	
5	// Text-only re-rank (CLAUDE.md Decision 3, mode 2): the model sees tag DESCRIPTIONS,
6	// never images. It returns the best 3 with a look name + one-sentence "why".
7	
8	export type DescItem = {
9	  category: string;
10	  subcategory?: string | null;
11	  colors: string[];
12	  /**
13	   * The signals the deterministic half already scores on. The model saw none of
14	   * them until 2026-08-15, which had two costs: the pattern-clash term could
15	   * only ORDER the shortlist while the model picked blind to it and was free to
16	   * choose the one combo with two loud pieces; and the "why" — the product's
17	   * differentiator — described fabric it was guessing at from a subcategory
18	   * name. Text costs nothing here (CLAUDE.md Decision 3: never images), and an
19	   * accurate sentence is the whole point of the call.
20	   */
21	  material?: string | null;
22	  texture?: string | null;
23	  pattern?: string | null;
24	};
25	
26	/**
27	 * Unremarkable values are omitted rather than printed.
28	 *
29	 * "solid" on every line is noise that buries the one patterned piece, and
30	 * "flat" says nothing a reader does not already assume. What is left is
31	 * exactly what should influence the choice.
32	 */
33	function describeItem(it: DescItem): string {
34	  const notes = [
35	    it.material?.toLowerCase(),
36	    it.texture && it.texture !== "Flat" ? it.texture.toLowerCase() : null,
37	    it.pattern && it.pattern !== "solid" ? it.pattern : null,
38	  ].filter(Boolean);
39	  const detail = [it.colors.join("/"), ...notes].filter(Boolean).join(", ");
40	  return `${it.subcategory ?? it.category}${detail ? ` (${detail})` : ""}`;
41	}
42	
43	export function describeCombos(combos: DescItem[][]): string {
44	  return combos.map((c, i) => `${i}. ` + c.map(describeItem).join(" + ")).join("\n");
45	}
46	
47	/**
48	 * Display budget for a look name — comfortably fits the "≤4 words" the prompt
49	 * asks for ("The Impeccable Charcoal Layer" = 29) with room to spare.
50	 */
51	export const NAME_MAX = 40;
52	
53	/**
54	 * Clamp a name to NAME_MAX on a word boundary.
55	 *
56	 * A name is decoration; the "why" is the product. This is a `transform`, not a
57	 * `.max()`, on purpose: the cap is never enforced on the model — CLAUDE.md's
58	 * `forStructuredOutput` strips `maxLength` because the API 400s on it — so a
59	 * hard bound here existed only as a post-hoc throw that failed the ENTIRE
60	 * generation and surfaced as "Couldn't reach the stylist". Repair, don't reject.
61	 */
62	export function clampName(raw: string): string {
63	  const s = raw.trim();
64	  if (s.length <= NAME_MAX) return s;
65	  const cut = s.slice(0, NAME_MAX);
66	  const lastSpace = cut.lastIndexOf(" ");
67	  return (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trimEnd();
68	}
69	
70	// The WIRE shape — what we ask the model for. Kept transform-free because
71	// `z.toJSONSchema` cannot represent a transform ("Transforms cannot be
72	// represented in JSON Schema"); the repair belongs on the way in, not the way out.
73	const PickShape = z.object({
74	  combo_index: z.number().int(),
75	  name: z.string().min(1),
76	  why: z.string().min(1),
77	});
78	
79	// Sanitised JSON Schema for Anthropic's output_config.format (strips min/max keywords
80	// that would 400 — real bounds re-enforced by RerankSchema.parse after the call).
81	export const rerankJsonSchema = forStructuredOutput(
82	  z.toJSONSchema(z.object({ picks: z.array(PickShape).length(3) })),
83	) as Record<string, unknown>;
84	
85	/** The most looks a daily drop ever shows. */
86	export const MAX_PICKS = 3;
87	
88	// The PARSE shape — same fields, plus the name repair.
89	//
90	// `.min(1)`, NOT `.length(3)`. The count is never enforced ON the model —
91	// `forStructuredOutput` strips minItems/maxItems because the API 400s on them —
92	// so an exact-3 rule existed only as a post-hoc throw, and a closet with fewer
93	// than three viable combos failed the ENTIRE generation as "Couldn't reach the
94	// stylist". That is a lie: the stylist answered, with everything the wardrobe
95	// could give. It bites hardest right after onboarding's "capture your first
96	// five", which is the magic moment. Repair, don't reject — the same stance as
97	// `clampName`. An empty array is still an error; there is nothing to show.
98	export const RerankSchema = z.object({
99	  picks: z.array(PickShape.extend({ name: z.string().min(1).transform(clampName) })).min(1),
100	});
101	export type RerankResult = z.infer<typeof RerankSchema>;
102	
103	/**
104	 * The variety instruction.
105	 *
106	 * "Pick the best 3" alone produces three versions of one outfit: the model is
107	 * optimising a single notion of "best", and the candidates handed to it are
